macro_rules! deps {
    () => {
        Protocol!();
        Error!();
    };
}

macro_rules! TransportWithoutIO {
    () => {
        deps!();
        # [doc = " This trait represents all transport related functions that don't require any input/output to be done which helps"] # [doc = " implementation to share more code across blocking and async programs."] pub trait TransportWithoutIO { # [doc = " If the handshake or subsequent reads failed with [`std::io::ErrorKind::PermissionDenied`], use this method to"] # [doc = " inform the transport layer about the identity to use for subsequent calls."] # [doc = " If authentication continues to fail even with an identity set, consider communicating this to the provider"] # [doc = " of the identity in order to mark it as invalid. Otherwise the user might have difficulty updating obsolete"] # [doc = " credentials."] # [doc = " Please note that most transport layers are unauthenticated and thus return [an error][Error::AuthenticationUnsupported] here."] fn set_identity (& mut self , _identity : gix_sec :: identity :: Account) -> Result < () , Error > { Err (Error :: AuthenticationUnsupported) } # [doc = " Returns the canonical URL pointing to the destination of this transport."] fn to_url (& self) -> Cow < '_ , BStr > ; # [doc = " If the actually advertised server version is contained in the returned slice or it is empty, continue as normal,"] # [doc = " assume the server's protocol version is desired or acceptable."] # [doc = ""] # [doc = " Otherwise, abort the fetch operation with an error to avoid continuing any interaction with the transport."] # [doc = ""] # [doc = " In V1 this means a potentially large list of advertised refs won't be read, instead the connection is ignored"] # [doc = " leaving the server with a client who potentially unexpectedly terminated the connection."] # [doc = ""] # [doc = " Note that `transport.close()` is not called explicitly."] # [doc = ""] # [doc = " Custom transports can override this to prevent any use of older protocol versions."] fn supported_protocol_versions (& self) -> & [Protocol] { & [] } # [doc = " Returns true if the transport provides persistent connections across multiple requests, or false otherwise."] # [doc = " Not being persistent implies that certain information has to be resent on each 'turn'"] # [doc = " of the fetch negotiation or that the end of interaction (i.e. no further request will be made) has to be indicated"] # [doc = " to the server for most graceful termination of the connection."] fn connection_persists_across_multiple_requests (& self) -> bool ; # [doc = " Pass `config` can be cast and interpreted by the implementation, as documented separately."] # [doc = ""] # [doc = " The caller must know how that `config` data looks like for the intended implementation."] fn configure (& mut self , config : & dyn Any) -> Result < () , Box < dyn std :: error :: Error + Send + Sync + 'static > > ; }
    };
}

TransportWithoutIO!();